import{_ as d,o as r,c as e,ag as a}from"./chunks/framework.KxDd3USm.js";const C=JSON.parse('{"title":"09 计算机系统基础","description":"","frontmatter":{},"headers":[],"relativePath":"09-计算机系统基础/index.md","filePath":"09-计算机系统基础/index.md"}'),o={name:"09-计算机系统基础/index.md"};function n(s,t,h,i,_,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="_09-计算机系统基础" tabindex="-1">09 计算机系统基础 <a class="header-anchor" href="#_09-计算机系统基础" aria-label="Permalink to &quot;09 计算机系统基础&quot;">​</a></h1><blockquote><p><strong>分值地位</strong>：基础知识选择题约 6–8 题，是单科里最稳定的计算题来源之一。★★★ 必会三类是 <strong>Cache 平均访问时间、磁盘容量/存取时间、串并联系统可靠性</strong>；补码、浮点数、寻址方式、RISC/CISC、校验码常以概念题或一步计算题出现。</p><p><strong>学习目标</strong>：学完本课后，你能——① 在固定位数下写出原码、反码、补码、移码并判断溢出；② 解释浮点数“阶码定范围、尾数定精度”，完成对阶；③ 认清 CPU 部件、存储层次、总线、中断与 DMA；④ 独立算出 Cache 平均时间、主存容量、磁盘容量和平均存取时间；⑤ 区分 RISC/CISC 与常见寻址方式；⑥ 计算串联、并联、混联系统可靠度；⑦ 完成奇偶、CRC、海明码的典型题。</p></blockquote><hr><h2 id="第一部分-本课导航" tabindex="-1">第一部分 本课导航 <a class="header-anchor" href="#第一部分-本课导航" aria-label="Permalink to &quot;第一部分 本课导航&quot;">​</a></h2><p>本章不单独对应下午案例大题，但它有一个特点：<strong>题型固定、公式短、计算可验算</strong>。学好后，上午卷的 6–8 分比背诵题更稳。</p><table tabindex="0"><thead><tr><th>模块</th><th>常见考法</th><th>目标</th></tr></thead><tbody><tr><td>数据表示</td><td>求负数补码、表示范围、浮点数对阶</td><td>会写、会判断</td></tr><tr><td>CPU 与存储</td><td>部件功能、局部性、RAM/ROM、主存编址</td><td>秒答概念题</td></tr><tr><td>Cache</td><td>平均访问时间、映射方式</td><td>必会计算</td></tr><tr><td>磁盘</td><td>容量、平均旋转等待、存取时间</td><td>必会计算</td></tr><tr><td>I/O、总线、中断</td><td>查询/中断/DMA；中断向量；三类总线</td><td>会按关键词归类</td></tr><tr><td>指令系统</td><td>寻址方式、RISC/CISC、流水线</td><td>会认题、会套公式</td></tr><tr><td>可靠性</td><td>串联、并联、混联、MTTF/MTTR/MTBF</td><td>必会计算</td></tr><tr><td>校验码</td><td>奇偶、CRC、海明码</td><td>理解原理并会一步计算</td></tr></tbody></table><p>建议顺序：先读讲义，再不看答案做 15 道选择题和 2 道综合题，最后做精华题。计算题必须动笔，尤其注意单位统一。</p><hr><hr>',9)])])}const p=d(o,[["render",n]]);export{C as __pageData,p as default};
